import type {Metadata} from 'next'
import {absoluteUrl, siteDescription, siteName} from './site'

/**
 * Site-wide fallback OG card — the image generated by app/opengraph-image.tsx.
 *
 * That file convention only covers the segment it sits in (the homepage), so it
 * is NOT inherited by /work, /play, etc. Every other page has to point at it
 * explicitly, which is what this constant is for.
 */
export const defaultOgImage = absoluteUrl('/opengraph-image')

interface PageMetadataInput {
  /** Goes into Next's `title`. The root layout's `%s — re.design` template
   *  applies to child segments, so pass the bare page name (e.g. "Work"). */
  title: string
  /** The full title as it should appear in a share card — no template is
   *  applied to OG/Twitter, so this must be spelled out (e.g. "Work — re.design"). */
  socialTitle: string
  description: string
  /** Site-relative, e.g. "/work" — used for both canonical and og:url. */
  path: string
  /** Absolute image URL. Falls back to the site-wide card. */
  image?: string
  imageAlt?: string
  type?: 'website' | 'article'
}

/**
 * Builds a page's metadata.
 *
 * The reason this exists rather than each page hand-writing an object: Next
 * merges metadata across segments **shallowly**, and duplicate keys are
 * *replaced*, not deep-merged. So a page that sets `openGraph: {title}` throws
 * away the root layout's entire `openGraph` block — siteName, locale, images and
 * all — and a page that sets `twitter: {title}` silently drops
 * `card: 'summary_large_image'`, downgrading its share card to a thumbnail.
 *
 * Emitting a complete object every time is the only safe pattern, so it's
 * centralised here instead of being re-derived (and re-broken) per page.
 */
export function pageMetadata({
  title,
  socialTitle,
  description,
  path,
  image,
  imageAlt,
  type = 'website',
}: PageMetadataInput): Metadata {
  const ogImage = image ?? defaultOgImage
  const alt = imageAlt ?? `${siteName} — ${siteDescription}`

  return {
    title,
    description,
    alternates: {canonical: path},
    openGraph: {
      type,
      siteName,
      locale: 'en_AU',
      url: path,
      title: socialTitle,
      description,
      images: [{url: ogImage, width: 1200, height: 630, alt}],
    },
    twitter: {
      card: 'summary_large_image',
      title: socialTitle,
      description,
      images: [ogImage],
    },
  }
}
